mapper.sql:
WHERE deleted = 0

  AND (expense_no LIKE CONCAT('%', #{keyword}, '%')
    OR expense_name LIKE CONCAT('%', #{keyword}, '%')
    OR related_order_no LIKE CONCAT('%', #{keyword}, '%')
    OR express_company LIKE CONCAT('%', #{keyword}, '%'))


  AND expense_type = #{expenseType}


  AND expense_date >= #{startDate}


  AND expense_date <= #{endDate}
